const l=JSON.parse('{"key":"v-070fef87","path":"/Projects-docs/Interview/%E5%BE%AE%E6%9C%8D%E5%8A%A1.html","title":"微服务","lang":"zh-CN","frontmatter":{"description":"微服务 基本概念 了解单体服务到微服务的差异化和优势，以及微服务技术的历史发展脉络，关注各阶段乃至最新的技术发展 单体服务与微服务的差异和优势 单体服务 定义：单体服务是一种将所有功能集成在一个应用程序中的架构风格。通常，一个单体应用将业务逻辑、数据库访问、客户端界面等集成在一起。 优势： 开发简单：所有代码在一个项目或解决方案中，易于管理和开发。 部署方便：整个应用作为一个单元部署。 缺点： 难以扩展：随着应用增长，代码库可能变得庞大且难以管理。 可靠性问题：一个模块的故障可能影响整个应用。 更新困难：更新或添加新功能可能需要重新部署整个应用。 微服务 定义：微服务架构是一种分散的架构风格，它将应用程序分解为一组较小的、独立的服务。这些服务围绕业务功能构建，可以独立部署、扩展和更新。 优势： 可扩展性：服务可以独立扩展，更适合大型、复杂的应用。 灵活性：不同服务可以使用不同的技术栈。 可靠性：一个服务的故障不会影响整个应用。 快速迭代：服务可以独立开发和部署，加速产品迭代。 缺点： 复杂性：管理多个服务比管理单一应用复杂。 通信成本：服务间通信增加了延迟和复杂性。 数据一致性：分布式系统中的数据管理比单体应用更为复杂。 微服务技术的历史发展 早期（2000年代初期）： 服务导向架构（SOA）兴起，强调服务间的松耦合。 兴起（2010年代初期）： 微服务概念被提出和普及。 云计算的发展提供了理想的基础设施支持。 成熟（2010年代中期至今）： 容器化技术（如 Docker）和容器编排（如 Kubernetes）的普及，进一步推动了微服务架构的实施。 DevOps 文化的兴起与微服务紧密结合。 最新发展： 服务网格（如 Istio）提供了微服务间通信的先进解决方案。 无服务器架构（Serverless）开始受到关注，进一步简化了微服务的部署和管理。","head":[["meta",{"property":"og:url","content":"https://ClearDewy.github.io/Projects-docs/Interview/%E5%BE%AE%E6%9C%8D%E5%8A%A1.html"}],["meta",{"property":"og:site_name","content":"Dewy-Wiki"}],["meta",{"property":"og:title","content":"微服务"}],["meta",{"property":"og:description","content":"微服务 基本概念 了解单体服务到微服务的差异化和优势，以及微服务技术的历史发展脉络，关注各阶段乃至最新的技术发展 单体服务与微服务的差异和优势 单体服务 定义：单体服务是一种将所有功能集成在一个应用程序中的架构风格。通常，一个单体应用将业务逻辑、数据库访问、客户端界面等集成在一起。 优势： 开发简单：所有代码在一个项目或解决方案中，易于管理和开发。 部署方便：整个应用作为一个单元部署。 缺点： 难以扩展：随着应用增长，代码库可能变得庞大且难以管理。 可靠性问题：一个模块的故障可能影响整个应用。 更新困难：更新或添加新功能可能需要重新部署整个应用。 微服务 定义：微服务架构是一种分散的架构风格，它将应用程序分解为一组较小的、独立的服务。这些服务围绕业务功能构建，可以独立部署、扩展和更新。 优势： 可扩展性：服务可以独立扩展，更适合大型、复杂的应用。 灵活性：不同服务可以使用不同的技术栈。 可靠性：一个服务的故障不会影响整个应用。 快速迭代：服务可以独立开发和部署，加速产品迭代。 缺点： 复杂性：管理多个服务比管理单一应用复杂。 通信成本：服务间通信增加了延迟和复杂性。 数据一致性：分布式系统中的数据管理比单体应用更为复杂。 微服务技术的历史发展 早期（2000年代初期）： 服务导向架构（SOA）兴起，强调服务间的松耦合。 兴起（2010年代初期）： 微服务概念被提出和普及。 云计算的发展提供了理想的基础设施支持。 成熟（2010年代中期至今）： 容器化技术（如 Docker）和容器编排（如 Kubernetes）的普及，进一步推动了微服务架构的实施。 DevOps 文化的兴起与微服务紧密结合。 最新发展： 服务网格（如 Istio）提供了微服务间通信的先进解决方案。 无服务器架构（Serverless）开始受到关注，进一步简化了微服务的部署和管理。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:updated_time","content":"2024-03-13T15:21:43.000Z"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:modified_time","content":"2024-03-13T15:21:43.000Z"}]]},"headers":[{"level":2,"title":"基本概念","slug":"基本概念","link":"#基本概念","children":[{"level":3,"title":"了解单体服务到微服务的差异化和优势，以及微服务技术的历史发展脉络，关注各阶段乃至最新的技术发展","slug":"了解单体服务到微服务的差异化和优势-以及微服务技术的历史发展脉络-关注各阶段乃至最新的技术发展","link":"#了解单体服务到微服务的差异化和优势-以及微服务技术的历史发展脉络-关注各阶段乃至最新的技术发展","children":[]},{"level":3,"title":"熟悉微服务的全景架构，明晰它的核心组件以及相关实例","slug":"熟悉微服务的全景架构-明晰它的核心组件以及相关实例","link":"#熟悉微服务的全景架构-明晰它的核心组件以及相关实例","children":[]},{"level":3,"title":"学习微服务架构的服务特点，如单一职责、轻量级通信、进程隔离等","slug":"学习微服务架构的服务特点-如单一职责、轻量级通信、进程隔离等","link":"#学习微服务架构的服务特点-如单一职责、轻量级通信、进程隔离等","children":[]}]},{"level":2,"title":"服务注册与发现","slug":"服务注册与发现","link":"#服务注册与发现","children":[{"level":3,"title":"etcd","slug":"etcd","link":"#etcd","children":[]},{"level":3,"title":"nacos","slug":"nacos","link":"#nacos","children":[]},{"level":3,"title":"zookeeper","slug":"zookeeper","link":"#zookeeper","children":[]}]},{"level":2,"title":"API网关服务","slug":"api网关服务","link":"#api网关服务","children":[{"level":3,"title":"Nginx","slug":"nginx","link":"#nginx","children":[]},{"level":3,"title":"Traefik","slug":"traefik","link":"#traefik","children":[]}]},{"level":2,"title":"分布式配置中心","slug":"分布式配置中心","link":"#分布式配置中心","children":[{"level":3,"title":"Nacos","slug":"nacos-1","link":"#nacos-1","children":[]},{"level":3,"title":"Apollo","slug":"apollo","link":"#apollo","children":[]}]},{"level":2,"title":"分布式事务","slug":"分布式事务","link":"#分布式事务","children":[{"level":3,"title":"了解分布式事务解决方案Seata，学习如何配置使用及基本架构","slug":"了解分布式事务解决方案seata-学习如何配置使用及基本架构","link":"#了解分布式事务解决方案seata-学习如何配置使用及基本架构","children":[]}]},{"level":2,"title":"服务通信","slug":"服务通信","link":"#服务通信","children":[{"level":3,"title":"restful api","slug":"restful-api","link":"#restful-api","children":[]},{"level":3,"title":"grpc","slug":"grpc","link":"#grpc","children":[]},{"level":3,"title":"异步消息","slug":"异步消息","link":"#异步消息","children":[]}]},{"level":2,"title":"服务治理","slug":"服务治理","link":"#服务治理","children":[{"level":3,"title":"限流","slug":"限流","link":"#限流","children":[]},{"level":3,"title":"降级、熔断","slug":"降级、熔断","link":"#降级、熔断","children":[]}]},{"level":2,"title":"可观测性","slug":"可观测性","link":"#可观测性","children":[{"level":3,"title":"服务监控","slug":"服务监控","link":"#服务监控","children":[]},{"level":3,"title":"服务追踪","slug":"服务追踪","link":"#服务追踪","children":[]},{"level":3,"title":"分布式日志","slug":"分布式日志","link":"#分布式日志","children":[]},{"level":3,"title":"服务运维","slug":"服务运维","link":"#服务运维","children":[]}]}],"git":{"createdTime":1710343303000,"updatedTime":1710343303000,"contributors":[{"name":"ClearDewy","email":"11166208+cleardewy@user.noreply.gitee.com","commits":1}]},"readingTime":{"minutes":38.34,"words":11503},"filePathRelative":"Projects-docs/Interview/微服务.md","localizedDate":"2024年3月13日","excerpt":"<h1> 微服务</h1>\\n<h2> 基本概念</h2>\\n<h3> 了解单体服务到微服务的差异化和优势，以及微服务技术的历史发展脉络，关注各阶段乃至最新的技术发展</h3>\\n<p><strong>单体服务与微服务的差异和优势</strong></p>\\n<ul>\\n<li>\\n<p><strong>单体服务</strong></p>\\n<ul>\\n<li>\\n<p><strong>定义</strong>：单体服务是一种将所有功能集成在一个应用程序中的架构风格。通常，一个单体应用将业务逻辑、数据库访问、客户端界面等集成在一起。</p>\\n</li>\\n<li>\\n<p><strong>优势</strong>：</p>\\n<ul>\\n<li>\\n<p>开发简单：所有代码在一个项目或解决方案中，易于管理和开发。</p>\\n</li>\\n<li>\\n<p>部署方便：整个应用作为一个单元部署。</p>\\n</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>缺点</strong>：</p>\\n<ul>\\n<li>\\n<p>难以扩展：随着应用增长，代码库可能变得庞大且难以管理。</p>\\n</li>\\n<li>\\n<p>可靠性问题：一个模块的故障可能影响整个应用。</p>\\n</li>\\n<li>\\n<p>更新困难：更新或添加新功能可能需要重新部署整个应用。</p>\\n</li>\\n</ul>\\n</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>微服务</strong></p>\\n<ul>\\n<li>\\n<p><strong>定义</strong>：微服务架构是一种分散的架构风格，它将应用程序分解为一组较小的、独立的服务。这些服务围绕业务功能构建，可以独立部署、扩展和更新。</p>\\n</li>\\n<li>\\n<p><strong>优势</strong>：</p>\\n<ul>\\n<li>\\n<p>可扩展性：服务可以独立扩展，更适合大型、复杂的应用。</p>\\n</li>\\n<li>\\n<p>灵活性：不同服务可以使用不同的技术栈。</p>\\n</li>\\n<li>\\n<p>可靠性：一个服务的故障不会影响整个应用。</p>\\n</li>\\n<li>\\n<p>快速迭代：服务可以独立开发和部署，加速产品迭代。</p>\\n</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>缺点</strong>：</p>\\n<ul>\\n<li>\\n<p>复杂性：管理多个服务比管理单一应用复杂。</p>\\n</li>\\n<li>\\n<p>通信成本：服务间通信增加了延迟和复杂性。</p>\\n</li>\\n<li>\\n<p>数据一致性：分布式系统中的数据管理比单体应用更为复杂。</p>\\n</li>\\n</ul>\\n</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>微服务技术的历史发展</strong></p>\\n<ul>\\n<li>\\n<p><strong>早期（2000年代初期）</strong>：</p>\\n<p>服务导向架构（SOA）兴起，强调服务间的松耦合。</p>\\n</li>\\n<li>\\n<p><strong>兴起（2010年代初期）</strong>：</p>\\n<ul>\\n<li>\\n<p>微服务概念被提出和普及。</p>\\n</li>\\n<li>\\n<p>云计算的发展提供了理想的基础设施支持。</p>\\n</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>成熟（2010年代中期至今）</strong>：</p>\\n<ul>\\n<li>容器化技术（如 Docker）和容器编排（如 Kubernetes）的普及，进一步推动了微服务架构的实施。</li>\\n<li>DevOps 文化的兴起与微服务紧密结合。</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>最新发展</strong>：</p>\\n<ul>\\n<li>\\n<p>服务网格（如 Istio）提供了微服务间通信的先进解决方案。</p>\\n</li>\\n<li>\\n<p>无服务器架构（Serverless）开始受到关注，进一步简化了微服务的部署和管理。</p>\\n</li>\\n</ul>\\n</li>\\n</ul>\\n</li>\\n</ul>","autoDesc":true}');export{l as data};
